# 1) Move id from <section id="X"> to its immediate <h2>, and from <article id="X"> to its immediate <h3>
# Pattern: <section id="foo">\n  <h2>Title</h2>  -> <section>\n  <h2 id="foo">Title</h2>

def move_section_ids(html):
    def repl(m):
        sid = m.group(1)
        rest = m.group(2)  # whitespace + h2 open attrs
        return f'<section>\n  <h2 id="{sid}"{rest}'
    return re.sub(
        r'<section\s+id="([^"]+)">\s*<h2(\s|>)',
        repl,
        html,
    )

def move_article_ids(html):
    def repl(m):
        aid = m.group(1)
        rest = m.group(2)
        return f'<article>\n    <h3 id="{aid}"{rest}'
    return re.sub(
        r'<article\s+id="([^"]+)">\s*<h3(\s|>)',
        repl,
        html,
    )

